"""Regenerates desk_page.py (the desk screener HTML as a Python string) from web/index.html.
api/scan.py serves it at /?desk=1. Run after editing web/index.html:  python tools/build_desk_page.py"""
import os
root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
html = open(os.path.join(root, "web", "index.html"), encoding="utf-8").read()
open(os.path.join(root, "desk_page.py"), "w", encoding="utf-8").write(
    '"""GENERATED by tools/build_desk_page.py from web/index.html. Do not edit by hand."""\nDESK_HTML = ' + repr(html) + "\n")
